//! Raw FFI bindings to libvpx, generated by bindgen in `build.rs` from the
//! headers of the libvpx actually linked. All use goes through the safe
//! wrappers in [`crate::encoder`] / [`crate::decoder`].
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/vpx_bindings.rs"));

// The `vp8_enc_control_id` enum is only referenced from C macros
// (VPX_CTRL_USE_TYPE), so bindgen does not emit it. The values below are
// taken verbatim from the installed <vpx/vp8cx.h> (libvpx 1.14) enum, in
// declaration order, and are stable ABI constants of libvpx.
pub const VP8E_SET_CPUUSED: i32 = 13;
pub const VP8E_SET_ENABLEAUTOALTREF: i32 = 14;
pub const VP8E_SET_STATIC_THRESHOLD: i32 = 17;
pub const VP8E_SET_ARNR_MAXFRAMES: i32 = 21;
pub const VP8E_SET_ARNR_STRENGTH: i32 = 22;
pub const VP8E_SET_FRAME_FLAGS: i32 = 27;
pub const VP9E_SET_TILE_COLUMNS: i32 = 33;
pub const VP9E_SET_SVC: i32 = 39;
pub const VP9E_SET_SVC_REF_FRAME_CONFIG: i32 = 52;
pub const VP9E_SET_ROW_MT: i32 = 55;
